use super::*;

/// Apply one [`Action`] to the store at `path`, returning the one-line note to print (or `None` when
/// there is nothing to say).
///
/// **Every failure here is a silent no-op, deliberately.** The child has already run and its exit code
/// is already decided; an unopenable db, a failed write or a missing directory must never surface as
/// anything the caller could mistake for the command's own failure. This is the same fail-open rule
/// `record_supply_fault` states for this store, and it is why this returns a note rather than a Result.
/// Append one `runs` row — what this command cost, regardless of whether it worked.
///
/// **Fail-open, exactly like [`apply_to_store`].** The child has run and its exit code is decided; a
/// missing hub, an unopenable db or a failed insert must never reach the caller. Returns whether the
/// row landed, for tests — nothing in the wrapper branches on it.
///
/// Unlike a fault, this records the CLEAN runs too. That is the point: a store holding only failures
/// can say what is broken but not whether the build is getting slower, and the second question is the
/// one `bsc mem build` was added to answer.
pub fn record_run(
    path: &std::path::Path,
    cost: &Cost,
    outcome: &Outcome,
    stage: &str,
    source: &str,
    cmd: &[String],
    now_ms: i64,
) -> bool {
    // An INTERRUPTED run is not a measurement. Ctrl-C on a build stops it part-way, so its wall clock
    // is however long someone waited before giving up and its peak is whatever it had reached — a
    // number that would sit in the trend looking like a fast cheap build. Same judgment `is_fault`
    // makes for faults, applied to cost.
    if outcome.interrupted {
        return false;
    }
    let Some(store) = crate::Store::open(path).ok() else { return false };
    store
        .conn
        .execute(
            "INSERT INTO runs (ts, stage, source, cmd, ok, exit_code, ms, peak_rss_bytes)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
            rusqlite::params![
                now_ms,
                stage,
                source,
                cmd.join(" "),
                i64::from(outcome.is_clean()),
                i64::from(outcome.exit_code()),
                cost.ms,
                cost.peak_rss_bytes,
            ],
        )
        .is_ok()
}
